-- Offsets are Unicode character offsets in the verified release baseline.
create table kf_modular.document_fragments (
  parent_key text not null, position integer not null,
  child_key text unique, markup text,
  check ((child_key is null) <> (markup is null)),
  primary key(parent_key, position)
);
alter table kf_modular.document_fragments enable row level security;
revoke all on kf_modular.document_fragments from public, anon, authenticated;
do $split$
