    for segment in select * from ranges where parent_id=parent.id order by start_pos loop
      if segment.start_pos<cursor_pos or segment.end_pos>parent.end_pos then raise exception 'Overlapping fragment'; end if;
      insert into kf_modular.document_fragments values(parent.id,slot,null,substr(source_html,cursor_pos+1,segment.start_pos-cursor_pos)),(parent.id,slot+1,segment.id,null);
      cursor_pos := segment.end_pos; slot := slot+2;
